const $=s=>document.querySelector(s);
const icons={discover:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M3 4h6q3 0 3 3v14q0-3-3-3H3z M21 4h-6q-3 0-3 3v14q0-3 3-3h6z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',art:'M4 3h16v18H4z M4 16l5-5 4 4 3-3 4 5 M14 7h.01',bookmark:'M6 3h12v19l-6-4-6 4z',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',crown:'m3 6 5 4 4-6 4 6 5-4-2 12H5z',help:'M9 9a3 3 0 1 1 4 3v2 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'m16 16 5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16 m-6-6 6 6-6 6',bell:'M5 17h14l-2-4V8a5 5 0 0 0-10 0v5z M10 21h4',chevron:'m9 5 7 7-7 7',filter:'M4 6h16 M7 12h10 M10 18h4',plus:'M12 4v16 M4 12h16',check:'m5 12 4 4L19 6',shield:'m12 2 9 4v6q-1 7-9 10-8-3-9-10V6z m-4 10 3 3 5-6',chart:'M4 3v18h18 M8 16v-5 M13 16V7 M18 16V4',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 3a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-4',wallet:'M3 5h17v15H3z M3 5V3h14 M15 10h7v6h-7z',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M4 4l3 2 M17 18l3 2 M20 4l-3 2 M7 18l-3 2 M12 1v3 M12 20v3 M1 12h3 M20 12h3',menu:'M3 6h18 M3 12h18 M3 18h18',logout:'M9 3H3v18h6 M8 12h13 m-5-5 5 5-5 5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.book}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const comics=[{id:'neon',title:'Neon Afterlight',author:'Kai Nakamura',genre:'Sci-fi',type:'membership',rating:'4.9',pages:28,chapters:12,art:'neon',desc:'In a city that never sees the sun, one courier carries its last light.'},{id:'sand',title:'The Dune Walker',author:'Amara Okafor',genre:'Fantasy',type:'purchase',rating:'4.8',pages:32,chapters:8,art:'sand',desc:'Beyond the salt kingdoms, a forgotten god is waking.'},{id:'forest',title:'Where the Wild Sleeps',author:'Ellis Morgan',genre:'Adventure',type:'free',rating:'4.9',pages:24,chapters:16,art:'forest',desc:'A map. A missing brother. A forest that remembers everything.'},{id:'sakura',title:'Last Spring in Kyoto',author:'Yuna Sato',genre:'Slice of life',type:'membership',rating:'4.7',pages:30,chapters:6,art:'sakura',desc:'Some goodbyes take an entire season.'},{id:'orbit',title:'Low Orbit',author:'Leo Park',genre:'Sci-fi',type:'both',rating:'4.8',pages:26,chapters:9,art:'orbit',desc:'Home is a moving target, two hundred miles above the earth.'},{id:'ember',title:'Ember & Ash',author:'Amara Okafor',genre:'Fantasy',type:'free',rating:'4.6',pages:22,chapters:4,art:'sand',desc:'Two sisters inherit a kingdom nobody wants to rule.'},{id:'quiet',title:'The Quiet Hours',author:'Ellis Morgan',genre:'Mystery',type:'purchase',rating:'4.8',pages:20,chapters:7,art:'forest',desc:'Every night at 3:17, the town forgets one person.'},{id:'red',title:'Redline District',author:'Kai Nakamura',genre:'Action',type:'both',rating:'4.9',pages:28,chapters:10,art:'neon',desc:'One last race through a city built on borrowed time.'}];
let saved;try{saved=JSON.parse(localStorage.getItem('panel-prototype')||'{}')}catch{saved={}}
const state={workspace:'reader',view:'Discover',genre:'All genres',query:'',...saved};state.saved||=[];state.purchases||=[];state.history||=[];state.drafts||=[];state.decisions||={};state.policies||={'Rights declaration':true,'Mature content labeling':true,'Pre-publication review':true,'Ads in guest previews':false,'Comments moderation':true};state.audit||=[];state.following||=[];
let reader=null,heroIndex=0,returnAction=null,lastFocus=null;
function persist(){if(state.email){state.accounts||={};state.accounts[state.email]={member:state.member,purchases:[...state.purchases]}}localStorage.setItem('panel-prototype',JSON.stringify(state))}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
const navs={reader:[['Discover','discover'],['All comics','book'],['New releases','spark'],['Art gallery','art'],['My library','bookmark'],['Reading history','clock'],['Membership','crown']],studio:[['Overview','discover'],['My publications','book'],['Art portfolio','art'],['Analytics','chart'],['Earnings','wallet'],['Audience','users'],['Studio settings','settings']],admin:[['Overview','discover'],['Review queue','shield'],['Content library','book'],['Authors & access','users'],['Memberships','crown'],['Ad placements','art'],['Policies','settings'],['Audit log','clock']]};
function go(view){reader=null;state.view=view;state.query='';state.genre='All genres';state.access='all';persist();render();window.scrollTo(0,0)}
function switchWorkspace(w){state.workspace=w;go(w==='reader'?'Discover':'Overview')}
function render(){const nav=navs[state.workspace]||navs.reader;const isReader=state.workspace==='reader';$('#app').innerHTML=`<aside class="sidebar"><a href="#" class="logo" data-go="Discover"><span class="logo-mark"><i></i><i></i><i></i></span>panel<span style="color:var(--purple)">.</span></a><div class="edition">STORIES LIVE HERE</div><div class="nav-group"><div class="nav-label">${isReader?'Explore':state.workspace==='studio'?'Author Studio':'Administration'}</div>${nav.map(([name,i],idx)=>`${isReader&&idx===4?'</div><div class="nav-group"><div class="nav-label">Your space</div>':''}<button class="nav-item ${state.view===name?'active':''}" data-go="${name}">${icon(i)}<span>${name}</span>${name==='Review queue'?'<span class="count">'+pendingReviews().length+'</span>':''}</button>`).join('')}</div><div class="sidebar-bottom">${isReader?`<div class="member-card">${icon('crown')}<strong>A world beyond the preview.</strong><p>Get closer to the stories you love. Become a Panel member.</p><button data-go="Membership">Explore membership</button></div>`:''}<button class="nav-item" data-action="help">${icon('help')}<span>Help & support</span></button><div class="workspace"><div class="nav-label" style="padding:0">Prototype workspace</div><select aria-label="Switch workspace" id="workspace"><option value="reader" ${isReader?'selected':''}>◈ Reader platform</option><option value="studio" ${state.workspace==='studio'?'selected':''}>▣ Author Studio</option><option value="admin" ${state.workspace==='admin'?'selected':''}>◇ Admin console</option></select></div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" aria-label="Open navigation" data-action="menu">${icon('menu')}</button><div class="breadcrumb">${isReader?'Explore':state.workspace==='studio'?'Author Studio':'Admin console'} <span style="margin:0 10px">/</span> <b>${state.view}</b></div><div class="top-actions"><button class="theme-toggle" data-action="theme" aria-label="Switch to dark theme" aria-pressed="false" title="Switch to dark theme"><svg class="icon theme-moon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 14A9 9 0 0 1 10 3.5 9 9 0 1 0 20.5 14Z"/></svg><svg class="icon theme-sun" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg></button><label class="search">${icon('search')}<input id="search" aria-label="Search comics and authors" placeholder="Search stories, artists & more" value="${esc(state.query)}"><span class="key">/</span></label><button class="plain" style="position:relative" aria-label="Notifications" data-action="notifications">${icon('bell')}<i class="notification-dot"></i></button>${state.user?`<button class="plain" data-action="account"><span class="avatar" style="width:31px;height:31px;font-size:12px">${esc(state.user.slice(0,1).toUpperCase())}</span>${esc(state.user)}</button>`:`<button class="plain" data-action="login">Log in</button><button class="primary" data-action="signup">Get started</button>`}</div></header><div class="content">${isReader?readerView():state.workspace==='studio'?studioView():adminView()}<footer class="footer"><span>© 2026 Panel. Made for stories worth telling.</span><div><button data-action="terms">Terms</button><button data-action="privacy">Privacy</button><button data-action="guidelines">Community guidelines</button></div></footer></div></main>`;bind();}
function intro(title,desc,action=''){return `<div class="intro"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function card(c){return `<article class="comic-card"><button class="cover" data-comic="${c.id}" aria-label="Read ${esc(c.title)}"><img src="assets/${c.art}.svg" alt="Illustrated cover of ${esc(c.title)}"><span class="badge ${c.type==='free'?'':'premium'}">${c.type==='free'?'Free to read':c.type==='purchase'?'Buy · $4.99':'✧ Premium'}</span><span class="cover-issue">VOL. 01</span><span class="cover-title"><small>A PANEL ORIGINAL</small>${esc(c.title)}</span></button><div class="card-title-row"><h3><button data-comic="${c.id}" style="padding:0;text-align:left">${esc(c.title)}</button></h3><span class="rating"><span>★</span> ${c.rating}</span></div><p class="author">${esc(c.author)}</p><div class="card-meta"><span class="tag">${c.genre}</span><span>${c.chapters} chapters</span><span style="margin-left:auto">${c.type==='free'?'Free series':c.type==='purchase'?'One-time purchase':'Members’ pick'}</span></div></article>`}
function hero(){let c=comics.filter(c=>!state.hidden?.includes(c.id))[[0,1,2][heroIndex]]||comics[0];return `<section class="hero"><img class="hero-art" src="assets/${c.art}.svg" alt="${esc(c.title)} illustrated cityscape"><div class="hero-copy"><div class="eyebrow"><span class="pill">✧ Editor’s pick</span><span>Original series</span></div><h2>${esc(c.title)}</h2><p>${esc(c.desc)}</p><button class="primary" data-comic="${c.id}">${icon('book')} Start reading</button><button class="secondary" aria-label="Save ${esc(c.title)}" data-save="${c.id}">${icon(state.saved.includes(c.id)?'check':'bookmark')}</button><div class="hero-meta">First 4 pages free &nbsp; · &nbsp; No account needed</div></div><div class="hero-credit">Story & art by ${esc(c.author)}</div><div class="hero-position">${[0,1,2].map(i=>`<button class="${heroIndex===i?'active':''}" aria-label="Featured story ${i+1}" data-hero="${i}"></button>`).join('')}</div></section>`}
function filters(){return `<div class="discovery-bar"><div class="filters">${['All genres','Fantasy','Sci-fi','Action','Adventure','Slice of life','Mystery'].map(g=>`<button class="chip ${state.genre===g?'active':''}" data-genre="${g}">${g}</button>`).join('')}</div><button class="filter-more" data-action="filters">${icon('filter')} Filters</button></div>`}
function filtered(list){return list.filter(c=>!state.hidden?.includes(c.id)&&(state.genre==='All genres'||c.genre===state.genre)&&(!state.access||state.access==='all'||c.type===state.access)&&(c.title+' '+c.author).toLowerCase().includes(state.query.toLowerCase()))}
function readerView(){if(state.view==='Membership')return membership();if(state.view==='Art gallery')return gallery();if(state.view==='My library'||state.view==='Reading history'){let list=comics.filter(c=>(state.view==='My library'?[...state.saved,...state.purchases]:state.history).includes(c.id));return intro(state.view,state.view==='My library'?'Your saved stories and purchased comics, all in one place.':'Pick up where your imagination left off.')+(list.length?`<div class="grid">${list.map(card).join('')}</div>`:`<div class="empty">${icon('bookmark')}<h2>Your next story is waiting.</h2><p>${state.view==='My library'?'Save a comic using the bookmark button in the reader.':'Open any comic to start your reading history.'}</p><button class="primary" data-go="All comics">Explore all comics</button></div>`)}let discover=state.view==='Discover'&&!state.query;let list=filtered(comics);if(state.view==='New releases')list=[...list].reverse();return intro(discover?'Find your next obsession.':state.query?`Results for “${esc(state.query)}”`:state.view,discover?'Independent voices. Extraordinary worlds. Stories that stay with you.':'Every story is open to explore. Read the first four pages without an account.',discover?`<span class="date">${icon('spark')} A little escape, every day</span>`:'')+(discover?hero()+continueReading():'')+filters()+`<section><div class="section-head"><div><h2>${discover?'Trending stories':state.query?'Matching stories':state.view==='New releases'?'Fresh off the drawing board':'The complete collection'} ${discover?'<span style="color:#b39bdf;font-size:20px">↗</span>':''}</h2><p>${discover?'The stories everyone is getting lost in.':list.length+' stories · All access types included'}</p></div>${discover?'<button class="text-link" data-go="All comics">View all comics '+icon('arrow')+'</button>':''}</div><div class="grid">${(discover?list.slice(0,4):list).map(card).join('')}</div>${!list.length?'<div class="empty"><h2>No stories found.</h2><p>Try another title, artist, or genre.</p><button class="secondary" data-action="resetFilters">Clear filters</button></div>':''}</section>${discover?`${state.member||state.ads?.['Discover sponsor banner']===false?'':`<div class="ad"><div class="ad-symbol">w.</div><div class="ad-copy"><strong>Your next great story starts with a sketch.</strong><p>Meet the drawing tools built for your imagination.</p></div><span class="ad-label">Sponsored</span><button class="secondary" data-action="sponsor">Explore tools ${icon('arrow')}</button></div>`}<section class="section"><div class="section-head"><div><h2>The minds behind the worlds</h2><p>Discover independent artists with something to say.</p></div><button class="text-link" data-go="Art gallery">Meet the artists ${icon('arrow')}</button></div><div class="artist-grid">${[['KN','Kai Nakamura','Sci-fi & urban worlds'],['AO','Amara Okafor','Fantasy & folklore'],['YS','Yuna Sato','Everyday extraordinary']].map(([a,n,d])=>`<div class="artist"><span class="avatar">${a}</span><div><strong>${n} <span style="color:var(--purple)">✦</span></strong><p>${d}</p></div><button class="text-link" data-follow="${n}">${state.following.includes(n)?'Following':'+ Follow'}</button></div>`).join('')}</div></section>`:''}`}
function membership(){return intro('More story. Less interruption.','Choose how you support the stories and artists you love.')+`<div class="notice">${state.member?'Your Panel Plus membership is active in this demo.':'Every comic includes a four-page guest preview. Membership unlocks titles marked Premium; purchase-only titles are sold separately.'}</div><div class="plan-grid"><article class="plan"><h2>The curious reader</h2><p>A place to begin. Always free.</p><div class="price">$0 <small>/ forever</small></div><ul><li>Browse the entire catalog</li><li>Four-page guest previews</li><li>Free comics after login</li><li>Save stories and follow artists</li><li>Ad-supported reading</li></ul><button class="secondary" data-action="signup">${state.user?'Your free account':'Create free account'}</button></article><article class="plan featured"><span class="status" style="background:var(--notice-bg);color:var(--purple)">For the endlessly curious</span><h2>Panel Plus</h2><p>Your next obsession is included.</p><div class="price">$8 <small>/ month</small></div><ul><li>Every membership-included comic</li><li>Ad-free reading</li><li>New chapters as they arrive</li><li>Support independent creators</li><li>Cancel before your next renewal</li></ul><button class="primary" data-action="subscribe">${state.member?'Manage membership':'Become a member'}</button></article><article class="plan"><h2>Make it yours</h2><p>One story. No subscription.</p><div class="price">$4.99 <small>/ eligible comic</small></div><ul><li>Access to the purchased comic</li><li>Read again in your library</li><li>Ad-free purchased reading</li><li>Pay only for what you choose</li><li>Look for the buy option</li></ul><button class="secondary" data-go="All comics">Find a comic</button></article></div><section class="panel"><h2>A few things worth knowing</h2><div class="policy-row"><div><strong>Does logging in unlock premium comics?</strong><p>No. A free account unlocks free comics. Premium access depends on each title’s membership or purchase options.</p></div></div><div class="policy-row"><div><strong>Where does my support go?</strong><p>Your membership supports participating creators. Authors can see their membership, purchase, and advertising revenue in Studio.</p></div></div><p class="demo-note">Prototype pricing. Checkout simulates access; no charges or real subscription are created.</p></section>`}
function gallery(showHeading=true){return (showHeading?intro('Beyond the panels.','Sketchbooks, world-building, and original art from our creators.'):'')+`<div class="gallery">${comics.slice(0,6).map((c,i)=>`<article><button style="padding:0;width:100%" data-art="${c.id}"><img src="assets/${c.art}.svg" alt="${esc(c.title)} concept illustration"></button><div class="art-info"><div><h3>${['City of borrowed light','The salt kingdoms','Into the hush','A season of goodbyes','Life above the clouds','A kingdom in embers'][i]}</h3><p>${esc(c.author)} · Concept art</p></div><button aria-label="Follow ${esc(c.author)}" data-follow="${esc(c.author)}">${icon(state.following.includes(c.author)?'check':'plus')}</button></div></article>`).join('')}</div>`}
function stats(items){return `<div class="stats">${items.map(([label,val,sub])=>`<div class="stat"><p>${label}</p><strong>${val}</strong><small>${sub}</small></div>`).join('')}</div>`}
function studioView(){let v=state.view;let head=intro(v==='Overview'?'Your stories are finding their people.':v,v==='Overview'?'Welcome back, Kai. Here’s what’s happening with your work.':'Create, manage, and grow your publishing practice.',`<button class="primary" data-action="upload">${icon('plus')} New publication</button>`);if(v==='My publications')return head+publications();if(v==='Art portfolio')return head+`<div class="notice">Publish illustrations alongside your comics. All new artwork goes through the same rights and content review.</div>`+gallery(false);if(v==='Studio settings')return head+`<form id="settingsForm" class="panel"><h2>Creator profile</h2><label class="field">Display name<input name="name" required value="${esc(state.creatorName||'Kai Nakamura')}"></label><label class="field">Bio<textarea name="bio">${esc(state.creatorBio||'Drawing the cities we dream about. Creator of Neon Afterlight and Redline District.')}</textarea></label><label class="field">Payout currency<select><option>USD — US dollar</option></select></label><button class="primary">Save profile</button><p class="demo-note">Authorized author demo. Identity verification and bank onboarding require a production service.</p></form>`;if(v==='Earnings')return head+stats([['Total earnings','$2,846.50','September 2026'],['Membership revenue','$1,840.00','64.6% of total'],['Comic purchases','$812.50','28.5% of total'],['Advertising','$194.00','6.9% of total']])+`<div class="panel"><div class="section-head"><h2>Payout history</h2><button class="secondary" data-action="export">Export statement</button></div>${table(['Period','Revenue','Platform fee','Net payout','Status'],[['August 2026','$2,610.00','$391.50','$2,218.50',status('Paid')],['July 2026','$2,320.00','$348.00','$1,972.00',status('Paid')]])}<p class="demo-note">Illustrative financial data. Platform fee shown at 15% for this prototype.</p></div>`;if(v==='Audience')return head+stats([['Followers','8,492','+624 this month'],['Returning readers','68%','+5.2% vs. last month'],['Average reading time','8m 24s','+1m 12s'],['Saved stories','2,184','+286 this month']])+`<div class="panel"><h2>What readers are saying</h2>${table(['Reader','Story','Comment'],[['Mia R.','Neon Afterlight','The city itself feels like a character.'],['Oliver T.','Redline District','That last panel. I need the next chapter.'],['Ari S.','Neon Afterlight','The color palettes are incredible.']])}</div>`;return head+stats([['Total reads','24,892','↗ 18.6% vs. last month'],['Active subscribers','1,284','↗ 12.4% vs. last month'],['Estimated revenue','$2,846.50','↗ 8.2% vs. last month'],['Publications',String(2+state.drafts.length),'2 live series']])+`<div class="split"><section class="panel"><div class="section-head"><h2>Readership over time</h2><span class="tag">September 2026</span></div><div class="chart" role="img" aria-label="Weekly readership growing from 2,800 to 7,900"><div class="bar" style="--h:34%"></div><div class="bar" style="--h:48%"></div><div class="bar" style="--h:40%"></div><div class="bar" style="--h:67%"></div><div class="bar" style="--h:58%"></div><div class="bar" style="--h:84%"></div><div class="bar" style="--h:94%"></div></div><div class="chart-labels"><span>Sep 1</span><span>Sep 5</span><span>Sep 9</span><span>Sep 13</span><span>Sep 17</span><span>Sep 21</span><span>Sep 25</span></div></section><section class="panel"><h2>Your next chapter</h2><p style="color:var(--muted);font-size:12px;line-height:1.9">Neon Afterlight is up 24% this week. Keep your readers in the loop with a new chapter.</p><button class="primary" data-action="upload">Create a publication</button><div class="notice" style="margin-top:25px">Publishing checklist<br>✓ Confirm your publishing rights<br>✓ Set an age rating<br>✓ Choose your access model<br>✓ Submit for editorial review</div></section></div>${v==='Analytics'?`<div class="panel"><h2>Discovery sources</h2>${table(['Source','Readers','Share'],[['Discover page','12,446','50%'],['Search','7,468','30%'],['Creator profiles','4,978','20%']])}</div>`:publications()}`}
function status(s){return `<span class="status ${['Published','Approved','Paid','Active'].includes(s)?'green':['Pending review','Needs changes','Invited'].includes(s)?'amber':s==='Rejected'||s==='Suspended'?'red':'grey'}">${s}</span>`}
function table(head,rows){return `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function publications(){return `<section class="panel"><div class="section-head"><h2>Your publications</h2><span class="tag">${state.drafts.length+2} publications</span></div>${table(['Title','Access','Status','Last updated','Action'],[['<strong>Neon Afterlight</strong>','Membership',status('Published'),'Sep 26, 2026','<button class="text-link" data-comic="neon">Preview</button>'],['<strong>Redline District</strong>','Membership + purchase',status('Published'),'Sep 23, 2026','<button class="text-link" data-comic="red">Preview</button>'],...state.drafts.map(d=>[`<strong>${esc(d.title)}</strong><br><small style="color:var(--muted)">${esc(d.kind)} · ${d.pages} pages</small>`,esc(d.access),status(d.status),'Just now',`<button class="text-link" data-draft="${d.id}">${d.status==='Draft'||d.status==='Needs changes'?'Edit & submit':'View submission'}</button>`])])}</section>`}
function pendingReviews(){return [{id:'rev1',title:'The Glass Garden',author:'Mira Chen',type:'New comic',issue:'Rights verification',art:'forest'},{id:'rev2',title:'After the Last Train',author:'Yuna Sato',type:'New chapter',issue:'Age rating review',art:'sakura'},{id:'rev3',title:'Orbital Study No. 8',author:'Leo Park',type:'Artwork',issue:'Standard review',art:'orbit'},...state.drafts.filter(d=>d.status==='Pending review').map(d=>({id:d.id,title:d.title,author:'Kai Nakamura',type:d.kind,issue:'Standard review',art:'neon'}))].filter(r=>!state.decisions[r.id])}
function queue(){return `<section class="panel"><div class="section-head"><h2>Awaiting a decision</h2><span class="status amber">${pendingReviews().length} pending</span></div>${table(['Publication','Author','Submission','Check','Action'],pendingReviews().map(r=>[`<strong>${esc(r.title)}</strong>`,esc(r.author),esc(r.type),status(r.issue),`<button class="text-link" data-review="${r.id}">Review submission ${icon('chevron')}</button>`]))}${pendingReviews().length?'':'<p class="empty">You’re all caught up. New submissions will appear here.</p>'}</section>`}
function adminView(){const v=state.view;let head=intro(v==='Overview'?'A healthy platform starts here.':v,v==='Overview'?'Your publishing operations, content quality, and community at a glance.':'Manage platform operations with clear ownership and an audit trail.',`<span class="status green">● Systems operational</span>`);if(v==='Review queue')return head+`<div class="notice">Review publishing rights, age ratings, and content policy before approving a submission. Requests for changes include actionable feedback for the author.</div>`+queue();if(v==='Policies')return head+`<section class="panel"><h2>Publishing guardrails</h2>${Object.entries(state.policies).map(([p,on])=>`<div class="policy-row"><div><strong>${p}</strong><p>${{'Rights declaration':'Require creators to confirm ownership or a publishing license.','Mature content labeling':'Require an age rating and content warnings for every submission.','Pre-publication review':'Route new publications to the review queue before public release.','Ads in guest previews':'Show advertising within the four-page guest reading experience.','Comments moderation':'Hold flagged comments for moderator review.'}[p]}</p></div><button class="toggle ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${p}" data-policy="${p}"></button></div>`).join('')}<p class="demo-note">Changes are stored locally and logged. Actual enforcement requires server-side rules.</p></section>`;if(v==='Audit log')return head+`<div class="panel"><div class="section-head"><h2>Recent actions</h2><button class="secondary" data-action="exportAudit">Export audit log</button></div>${table(['Time','Actor','Action','Details'],[...state.audit.map(a=>[esc(a.time),'Admin demo',esc(a.action),esc(a.details)]),['Sep 29, 09:42','Editorial team','Approved publication','Neon Afterlight · Chapter 12'],['Sep 28, 16:21','Platform admin','Updated policy','Mature content labeling enabled']])}</div>`;if(v==='Authors & access')return head+`<section class="panel"><div class="section-head"><h2>Authorized creators</h2><button class="primary" data-action="invite">${icon('plus')} Invite author</button></div>${table(['Author','Role','Status','Publications','Action'],[['Kai Nakamura','Author',status(state.suspended?'Suspended':'Active'),'2',`<button class="text-link" data-action="suspend">${state.suspended?'Restore access':'Suspend access'}</button>`],['Amara Okafor','Author',status('Active'),'2','<button class="text-link" data-creator="Amara Okafor">View permissions</button>'],['Yuna Sato','Author',status('Active'),'1','<button class="text-link" data-creator="Yuna Sato">View permissions</button>'],...(state.invites||[]).map(e=>[esc(e),'Author',status('Invited'),'0','Awaiting acceptance'])])}</section><div class="notice" style="margin-top:20px">Authors can manage their own publications. Moderators review content. Only admins manage access, commercial settings, and platform policies.</div>`;if(v==='Content library')return head+`<section class="panel">${table(['Publication','Author','Access','Status','Action'],comics.map(c=>[c.title,c.author,c.type,status(state.hidden?.includes(c.id)?'Hidden':'Published'),`<button class="text-link" data-hide="${c.id}">${state.hidden?.includes(c.id)?'Restore':'Unpublish'}</button>`]))}</section>`;if(v==='Memberships')return head+stats([['Active members','3,842','+14.8% this month'],['Monthly recurring revenue','$30,736','Panel Plus · $8/month'],['Renewal rate','94.2%','Last 30 days'],['Cancellations','82','Last 30 days']])+`<div class="panel"><h2>Membership catalog</h2>${table(['Plan','Price','Entitlements','Status'],[['Panel Plus','$8 / month','Membership-enabled comics · Ad-free reading',status('Active')],['Individual purchase','$4.99 / eligible comic','Persistent access to purchased comic',status('Active')]])}<p class="demo-note">Illustrative metrics. Billing and entitlement records require a payment integration.</p></div>`;if(v==='Ad placements')return head+stats([['Ad impressions','128,420','September 2026'],['Click-through rate','1.82%','+0.3% vs last month'],['Estimated revenue','$642.10','Before creator revenue share'],['Active placements','3','All labeled sponsored']])+`<section class="panel"><h2>Placement controls</h2>${['Discover sponsor banner','Free comic reader footer','Art gallery sponsor'].map((p,i)=>`<div class="policy-row"><div><strong>${p}</strong><p>${i===1?'Eligible free readers only; excluded for members and purchased comics.':'Contextual sponsorship. No behavioral targeting in the prototype.'}</p></div><button class="toggle ${state.ads?.[p]===false?'':'on'}" role="switch" aria-checked="${state.ads?.[p]!==false}" aria-label="${p}" data-ad="${p}"></button></div>`).join('')}</section>`;return head+stats([['Published comics','248','18 added this month'],['Authorized authors','42','4 pending invitations'],['Pending reviews',String(pendingReviews().length),'Target turnaround: 24 hours'],['Open reports',String(state.reports?.length||0),'Reader-submitted reports']])+queue()+`<div class="split"><section class="panel"><h2>Platform health</h2>${table(['Check','State'],[['Content delivery',status('Active')],['Membership access',status('Active')],['Moderation queue',status('Active')]])}<p class="demo-note">Demonstration status, not live monitoring.</p></section><section class="panel"><h2>Reader reports</h2>${state.reports?.length?state.reports.map(r=>`<div class="policy-row"><div><strong>${esc(r.title)}</strong><p>${esc(r.reason)}</p></div><button class="text-link" data-resolve="${r.id}">Resolve</button></div>`).join(''):'<p style="color:var(--muted);font-size:12px">No open reader reports. Reports from the comic reader appear here.</p>'}</section></div>`}
function modal(html,wide=false){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="Panel dialog" tabindex="-1"><button class="close" aria-label="Close dialog" data-action="close">×</button>${html}</section></div>`;document.body.style.overflow='hidden';bindModal();$('.modal').focus()}
function closeModal(){ $('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus?.() }
function auth(signup=false){modal(`<h2>${signup?'Your next chapter starts here.':'Welcome back.'}</h2><p>${signup?'Save stories, follow your favorite creators, and keep reading free comics.':'Log in to pick up where you left off.'}</p><form id="authForm"><label class="field">${signup?'Display name':'Name'}<input name="name" autocomplete="nickname" required placeholder="What should we call you?" maxlength="30"></label><label class="field">Email address<input type="email" name="email" autocomplete="email" required placeholder="you@example.com"></label><button class="primary" style="width:100%">${signup?'Create demo account':'Log in to demo'}</button><p class="demo-note">Prototype session only. Use a fictional email; no password or real account is needed.</p></form><button class="text-link" data-action="${signup?'login':'signup'}">${signup?'Already have an account? Log in':'New to Panel? Create an account'}</button>`)}
function startReader(id,page=null){const c=comics.find(c=>c.id===id);if(!c)return;reader={id,page:page||Math.min(state.progress?.[id]||1,entitled(c)?c.pages:4)};if(!state.history.includes(id))state.history.unshift(id);persist();renderReader()}
function entitled(c){return !!state.user&&(c.type==='free'||state.purchases.includes(c.id)||state.member&&['membership','both'].includes(c.type))}
function renderReader(){const c=comics.find(c=>c.id===reader.id);const allowed=reader.page<=4||entitled(c);const lines=['They said the city had forgotten how to dream.','But someone was still leaving the lights on.','At the edge of the familiar, a new world waited.','Some doors only open when you stop running.'];let gateTitle=!state.user?'Every great story has a next page.':c.type==='free'?'Keep reading for free.':'The story is just getting started.';modal(`<div class="reader-header"><div><h2>${esc(c.title)}</h2><p style="margin:4px 0 0">Chapter 1 · ${esc(c.author)}</p></div><span class="tag">${entitled(c)?'Full access':'4-page preview'}</span></div><div class="reader-layout"><div>${allowed?`<div class="comic-page"><img src="assets/${c.art}.svg" alt="Illustrative prototype comic page ${reader.page}" style="object-position:${40+reader.page*8}% ${reader.page%2?30:80}%;filter:hue-rotate(${reader.page*7}deg)"><div class="speech">${['Is anybody still out there?','There has to be another way.','Wait. Did you see that?','This is only the beginning.'][(reader.page-1)%4]}</div><div class="caption">${lines[(reader.page-1)%4]}</div><span style="position:absolute;bottom:6px;left:10px;font-size:9px;color:white">${reader.page.toString().padStart(2,'0')} / ${c.pages} · Prototype story panels</span></div>`:`<div class="gate">${icon(c.type==='free'?'book':'crown')}<h2 style="margin:20px 0 10px">${gateTitle}</h2><p>You’ve read the 4 free preview pages of ${esc(c.title)}. ${!state.user?'Create a free account to continue with the right access for this title.':c.type==='membership'?'This title is included with Panel Plus.':c.type==='purchase'?'This title is sold individually and is not included with membership.':'Read with Panel Plus or buy this comic once.'}</p>${!state.user?'<button class="primary" data-action="readerLogin">Create account or log in</button>':''}${c.type!=='free'&&c.type!=='purchase'?'<button class="primary" data-action="subscribe">Read with Panel Plus · $8/month</button>':''}${c.type==='purchase'||c.type==='both'?`<button class="secondary" data-buy="${c.id}">Buy this comic · $4.99</button>`:''}<button class="text-link" style="margin-top:20px" data-action="close">Keep exploring</button></div>`}<div class="reader-controls"><button class="secondary" data-page="${reader.page-1}" ${reader.page<=1?'disabled':''}>Previous</button><span>Page ${Math.min(reader.page,c.pages)} of ${c.pages}</span><button class="primary" data-page="${reader.page+1}" ${!allowed||reader.page>=c.pages?'disabled':''}>${reader.page===4&&!entitled(c)?'Continue reading':'Next page'}</button></div></div><aside class="reader-aside"><span class="tag">${c.genre}</span><h3 style="font:600 20px 'Space Grotesk';margin-top:20px">${esc(c.title)}</h3><p>${esc(c.desc)}</p><p>★ ${c.rating} reader rating<br>${c.chapters} chapters · ${c.pages} pages in chapter 1</p><button class="secondary" style="width:100%;margin-top:14px" data-save="${c.id}">${icon(state.saved.includes(c.id)?'check':'bookmark')}${state.saved.includes(c.id)?'Saved to library':'Save to library'}</button><button class="text-link" style="margin:18px 0" data-follow="${esc(c.author)}">${state.following.includes(c.author)?'✓ Following creator':'+ Follow '+c.author}</button><hr style="border:0;border-top:1px solid var(--line)"><p>${c.type==='free'?'Free with an account':c.type==='membership'?'Included with Panel Plus':c.type==='purchase'?'Individual purchase · $4.99':'Panel Plus or buy for $4.99'}</p><button class="text-link" data-report="${c.id}">Report this publication</button><p class="demo-note" style="margin-top:22px">Sample art and dialogue demonstrate the reader. Preview restrictions are simulated locally.</p></aside></div>`,true);if(allowed){state.progress||={};state.progress[c.id]=reader.page;persist()}}
function checkout(type,id){if(type==='membership'&&state.member){modal(`<h2>Your Panel Plus membership</h2><p>Your demo membership is active. You can read every membership-included title without ads.</p><div class="notice">Panel Plus · $8/month<br>Prototype subscription; no payment collected.</div><div class="form-actions"><button class="secondary" data-action="cancelMembership">Cancel demo membership</button><button class="primary" data-action="close">Keep reading</button></div>`);return}if(!state.user){returnAction=()=>checkout(type,id);auth(true);return}const c=comics.find(c=>c.id===id);modal(`<h2>${type==='membership'?'Make room for more stories.':'Add this story to your library.'}</h2><p>${type==='membership'?'Panel Plus unlocks membership-included comics and ad-free reading.':esc(c.title)+' by '+esc(c.author)}</p><div class="panel" style="margin-bottom:20px"><div class="section-head"><strong>${type==='membership'?'Panel Plus':'Individual comic'}</strong><strong>${type==='membership'?'$8.00 / month':'$4.99'}</strong></div><p>${type==='membership'?'Renews monthly. Cancel before renewal. Purchase-only titles excluded.':'One-time purchase. Access to this comic remains in your library without a membership.'}</p></div><p class="demo-note">Demo checkout. No card information is collected and no money will be charged. Production checkout must display final taxes and billing terms.</p><button class="primary" style="width:100%" data-checkout="${type}" data-id="${id||''}">Confirm demo ${type==='membership'?'membership':'purchase'}</button>`)}
function upload(draftId){const d=state.drafts.find(d=>d.id===draftId);if(state.suspended){modal('<h2>Publishing access is suspended</h2><p>Contact your platform administrator to request a review of your author access.</p>');return}if(d&&!['Draft','Needs changes'].includes(d.status)){modal(`<h2>${esc(d.title)}</h2><p>${status(d.status)}</p><p>${esc(d.synopsis)}</p><div class="notice">${d.pages} pages · ${esc(d.access)} · ${esc(d.rating)}<br>${esc(d.feedback||'Your submission is in the editorial workflow.')}</div>`);return}modal(`<h2>${d?'Edit publication':'Give your next story a home.'}</h2><p>Save a draft or submit it to the editorial team for review.</p>${d?.feedback?`<div class="notice">Editor feedback: ${esc(d.feedback)}</div>`:''}<form id="uploadForm" data-id="${d?.id||''}"><label class="field">Title<input name="title" required maxlength="80" value="${esc(d?.title||'')}" placeholder="The name of your next world"></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:15px"><label class="field">Publication type<select name="kind">${['Comic','Chapter','Artwork'].map(v=>`<option ${d?.kind===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Access model<select name="access">${['Free','Membership','Individual purchase','Membership + purchase'].map(v=>`<option ${d?.access===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="field">Synopsis<textarea name="synopsis" required maxlength="500" placeholder="Introduce your story to readers.">${esc(d?.synopsis||'')}</textarea></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:15px"><label class="field">Number of pages<input name="pages" type="number" min="5" max="300" value="${d?.pages||24}" required></label><label class="field">Age rating<select name="rating"><option>Everyone</option><option ${d?.rating==='Teen (13+)'?'selected':''}>Teen (13+)</option><option ${d?.rating==='Mature (18+)'?'selected':''}>Mature (18+)</option></select></label></div><label class="field">Cover or manuscript (optional demo attachment)<input name="file" type="file" accept="image/*,.pdf"><small>File metadata only; this prototype does not upload or store the file.</small></label><label style="display:flex;gap:10px;font-size:11px;line-height:1.7"><input type="checkbox" name="rights" ${d?.rights?'checked':''}>I own this work or have permission to publish it, and have reviewed the community guidelines.</label><div id="formError" role="alert" style="color:var(--error);font-size:11px;margin-top:10px"></div><div class="form-actions"><button class="secondary" type="submit" name="intent" value="draft">Save draft</button><button class="primary" type="submit" name="intent" value="submit">Submit for review</button></div></form>`)}
function review(id){const r=pendingReviews().find(r=>r.id===id);if(!r)return;modal(`<h2>Review publication</h2><div class="review-preview"><img src="assets/${r.art}.svg" alt="Submission cover"><div><h3>${esc(r.title)}</h3><p>${esc(r.author)}<br>${esc(r.type)}</p>${status(r.issue)}</div></div><div class="notice">Check rights ownership, age rating, restricted content, and misleading metadata before publishing.</div><form id="reviewForm" data-id="${id}"><label class="field">Decision<select name="decision"><option>Approved</option><option>Needs changes</option><option>Rejected</option></select></label><label class="field">Editorial note<textarea name="note" placeholder="Explain your decision. Required for changes or rejection."></textarea></label><label style="font-size:11px;display:flex;gap:9px"><input type="checkbox" name="checked" required>I completed the rights and content policy checks.</label><div id="formError" role="alert" style="color:var(--error);font-size:11px;margin-top:12px"></div><button class="primary" style="margin-top:20px">Save decision</button></form>`)}
function log(action,details){state.audit.unshift({time:new Date().toLocaleString('en-GB',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}),action,details});persist()}
function exportFile(name,content,type='text/csv'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export downloaded')}
function bind(){window.panelTheme.sync();document.querySelectorAll('#app [data-go]').forEach(el=>el.onclick=e=>{e.preventDefault();go(el.dataset.go)});$('#workspace').onchange=e=>switchWorkspace(e.target.value);$('#search').onkeydown=e=>{if(e.key==='Enter'){state.query=e.target.value;state.view=state.workspace==='reader'?'All comics':state.view;render();if(state.workspace!=='reader')toast('Catalog search is available in the Reader workspace')}};bindActions($('#app'));const settings=$('#settingsForm');if(settings)settings.onsubmit=e=>{e.preventDefault();const f=new FormData(settings);state.creatorName=f.get('name');state.creatorBio=f.get('bio');persist();toast('Creator profile saved')};}
function bindActions(root){root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));root.querySelectorAll('[data-comic]').forEach(b=>b.onclick=()=>startReader(b.dataset.comic));root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(s=>s!==id):[...state.saved,id];persist();toast(state.saved.includes(id)?'Saved to your library':'Removed from library');render();if(reader&&$('#modal-root').innerHTML)renderReader()});root.querySelectorAll('[data-follow]').forEach(b=>b.onclick=()=>{const n=b.dataset.follow;if(!state.user){returnAction=()=>{state.following.push(n);persist();render();toast('Following '+n)};auth(true);return}state.following=state.following.includes(n)?state.following.filter(a=>a!==n):[...state.following,n];persist();render();if($('#modal-root').innerHTML&&reader)renderReader();toast(state.following.includes(n)?'Following '+n+' · New chapters appear in notifications':'Unfollowed '+n)});root.querySelectorAll('[data-genre]').forEach(b=>b.onclick=()=>{state.genre=b.dataset.genre;render()});root.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{heroIndex=Number(b.dataset.hero);render()});root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{reader.page=Number(b.dataset.page);renderReader()});root.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>checkout('purchase',b.dataset.buy));root.querySelectorAll('[data-checkout]').forEach(b=>b.onclick=()=>{if(b.dataset.checkout==='membership')state.member=true;else if(!state.purchases.includes(b.dataset.id))state.purchases.push(b.dataset.id);persist();closeModal();render();toast('Demo access activated. Enjoy your story.');if(reader)renderReader()});root.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>upload(b.dataset.draft));root.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>review(b.dataset.review));root.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>{const p=b.dataset.policy;state.policies[p]=!state.policies[p];log('Updated policy',p+' '+(state.policies[p]?'enabled':'disabled'));render();toast('Policy updated and recorded in audit log')});root.querySelectorAll('[data-ad]').forEach(b=>b.onclick=()=>{state.ads||={};let p=b.dataset.ad;state.ads[p]=state.ads[p]===false;log('Updated ad placement',p);render();toast('Ad placement updated')});root.querySelectorAll('[data-hide]').forEach(b=>b.onclick=()=>{const id=b.dataset.hide;const hidden=state.hidden?.includes(id);modal(`<h2>${hidden?'Restore':'Unpublish'} this comic?</h2><p>${hidden?'This comic will be visible in the public catalog again.':'This comic will be removed from public discovery. Existing purchases should retain access in production.'}</p><button class="primary" id="confirmVisibility">${hidden?'Restore publication':'Confirm unpublish'}</button>`);$('#confirmVisibility').onclick=()=>{state.hidden||=[];state.hidden=hidden?state.hidden.filter(x=>x!==id):[...state.hidden,id];log(hidden?'Restored publication':'Unpublished',id);closeModal();render();toast('Publication visibility updated')}});root.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{const c=comics.find(c=>c.id===b.dataset.report);modal(`<h2>Report publication</h2><p>Tell our moderation team what needs attention in ${esc(c.title)}.</p><form id="reportForm"><label class="field">Reason<select name="reason"><option>Copyright or ownership concern</option><option>Incorrect age rating</option><option>Harmful or prohibited content</option><option>Misleading metadata</option><option>Other concern</option></select></label><label class="field">Details<textarea name="detail" required maxlength="500" placeholder="Describe your concern."></textarea></label><button class="primary">Send report</button></form>`);$('#reportForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.reports||=[];state.reports.push({id:Date.now(),title:c.title,reason:f.get('reason')+': '+f.get('detail')});persist();closeModal();toast('Report received. The moderation team will review it.')}});root.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>{state.reports=state.reports.filter(r=>String(r.id)!==b.dataset.resolve);log('Resolved reader report',b.dataset.resolve);render();toast('Report resolved')});root.querySelectorAll('[data-art]').forEach(b=>b.onclick=()=>{const c=comics.find(c=>c.id===b.dataset.art);modal(`<h2>${esc(c.title)} · Concept art</h2><p>Original world-building by ${esc(c.author)}</p><img src="assets/${c.art}.svg" alt="${esc(c.title)} concept art" style="width:100%;max-height:65vh;object-fit:contain"><button class="primary" style="margin-top:15px" data-comic="${c.id}">Explore the story</button>`,true)});root.querySelectorAll('[data-creator]').forEach(b=>b.onclick=()=>modal(`<h2>${esc(b.dataset.creator)}</h2><p>Authorized author</p><div class="notice">Can create drafts, submit their own comics and art, view their analytics, and review earnings.<br><br>Cannot publish without review, edit other authors’ work, change platform policy, or access admin billing.</div>`));}
function bindModal(){bindActions($('#modal-root'));const authForm=$('#authForm');if(authForm)authForm.onsubmit=e=>{e.preventDefault();state.user=new FormData(e.target).get('name').trim();if(!state.user)return;state.email=String(new FormData(e.target).get('email')).toLowerCase();const account=state.accounts?.[state.email];state.member=account?.member||false;state.purchases=account?.purchases||[];persist();closeModal();render();toast('Welcome to Panel, '+state.user);if(returnAction){const fn=returnAction;returnAction=null;fn()}else if(reader)renderReader()};const uploadForm=$('#uploadForm');if(uploadForm)uploadForm.onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const submit=e.submitter.value==='submit';if(submit&&!f.get('rights')){$('#formError').textContent='Confirm your publishing rights before submitting.';return}const existing=state.drafts.find(d=>d.id===uploadForm.dataset.id);const d={id:existing?.id||'draft'+Date.now(),title:f.get('title').trim(),kind:f.get('kind'),access:f.get('access'),synopsis:f.get('synopsis'),pages:Number(f.get('pages')),rating:f.get('rating'),rights:!!f.get('rights'),status:submit?'Pending review':'Draft'};if(!d.title)return;if(existing)Object.assign(existing,d);else state.drafts.push(d);delete state.decisions[d.id];persist();closeModal();go('My publications');toast(submit?'Submitted for editorial review':'Draft saved')};const reviewForm=$('#reviewForm');if(reviewForm)reviewForm.onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),decision=f.get('decision'),note=f.get('note').trim();if(decision!=='Approved'&&!note){$('#formError').textContent='Add actionable feedback for this decision.';return}const id=reviewForm.dataset.id;state.decisions[id]={decision,note};const d=state.drafts.find(d=>d.id===id);if(d){d.status=decision==='Approved'?'Published':decision;d.feedback=note;if(decision==='Approved')syncPublications()}log('Review: '+decision,id+(note?' · '+note:''));closeModal();render();toast('Decision saved and author notified in the demo')};}
function action(a){switch(a){case'theme':window.panelTheme.toggle();return;case'close':returnAction=null;reader=null;closeModal();return;case'menu':$('.sidebar').classList.toggle('open');return;case'login':auth();return;case'signup':if(state.user){toast('You are already signed in');return}auth(true);return;case'readerLogin':auth(true);return;case'subscribe':checkout('membership');return;case'cancelMembership':state.member=false;persist();closeModal();render();toast('Demo membership canceled');return;case'upload':upload();return;case'account':modal(`<h2>Your reading space</h2><p>Signed in as ${esc(state.user)}.</p><div class="notice">${state.member?'Panel Plus member':'Free reader'}<br>${state.saved.length} saved stories · ${state.purchases.length} purchases · ${state.following.length} followed creators</div><div class="form-actions"><button class="secondary" data-action="logout">Log out</button><button class="primary" data-action="close">Keep exploring</button></div>`);return;case'logout':state.accounts||={};if(state.email)state.accounts[state.email]={member:state.member,purchases:[...state.purchases]};state.user=null;state.email=null;state.member=false;state.purchases=[];persist();closeModal();render();reader=null;toast('Logged out of demo session');return;case'notifications':modal(`<h2>Your story feed</h2><p>New chapters from creators you follow.</p>${state.following.length?state.following.map(n=>`<div class="policy-row"><div><strong>${esc(n)}</strong><p>A new story is waiting in the catalog.</p></div><button class="text-link" data-comic="${comics.find(c=>c.author===n)?.id||'neon'}">Read</button></div>`).join(''):'<div class="notice">Follow a creator to make this space yours. Their new stories will appear here.</div>'}<div class="policy-row"><div><strong>Weekly reading digest</strong><p>Get a weekly roundup of your followed creators.</p></div><button class="toggle ${state.digest?'on':''}" role="switch" aria-label="Weekly reading digest" aria-checked="${!!state.digest}" id="digestToggle"></button></div><p class="demo-note">Notification and email preferences are simulated; no emails are sent.</p>`);$('#digestToggle').onclick=()=>{state.digest=!state.digest;persist();action('notifications');toast('Digest preference saved')};return;case'filters':modal(`<h2>Find your kind of story</h2><form id="filterForm"><label class="field">Access type<select name="access"><option value="all">All comics</option><option value="free">Free with an account</option><option value="membership">Membership included</option><option value="purchase">Individual purchase</option><option value="both">Membership or purchase</option></select></label><button class="primary">Apply filters</button></form>`);$('#filterForm').onsubmit=e=>{e.preventDefault();state.access=new FormData(e.target).get('access');closeModal();render()};return;case'resetFilters':state.genre='All genres';state.query='';state.access='all';render();return;case'help':modal(`<h2>A little help, when you need it.</h2><p>Browse every comic without an account. Open a story to read its first four pages.</p><div class="notice"><strong>Readers</strong><br>Free comics require login after page 4. Premium comics show their membership or purchase options.<br><br><strong>Creators</strong><br>Choose Author Studio in the workspace selector, create a publication, and submit it for review.<br><br><strong>Admins</strong><br>Choose Admin console to review submissions, manage author access, and set policies.</div><p class="demo-note">Workspace switching demonstrates role-specific screens; it is not production authentication.</p>`);return;case'terms':case'privacy':case'guidelines':modal(`<h2>${a==='terms'?'Terms of use':a==='privacy'?'Privacy & your data':'Community guidelines'}</h2><p>${a==='terms'?'Creators must hold publishing rights. Readers must respect creators’ intellectual property. Membership access and individually purchased access are distinct.':a==='privacy'?'This prototype stores demo preferences in your browser. It does not send account information, purchases, or uploads to a server. Google Fonts may load externally.':'Publish only work you own or are licensed to share. Label mature themes accurately. Do not publish harassment, hateful content, exploitative material, or deceptive metadata. Readers can report concerns from any comic.'}</p><p class="demo-note">Draft product copy for the prototype. Production policies require complete jurisdiction-appropriate terms, privacy notices, and appeal procedures.</p>`);return;case'sponsor':modal('<h2>A space for relevant sponsorships.</h2><p>This sample placement represents a contextual campaign for drawing tools. Sponsorships are visibly labeled and kept separate from editorial picks.</p><div class="notice">Potential packages: discovery banners, sponsored artist workshops, and clearly labeled creator collaborations.</div><p class="demo-note">Fictional sponsor. No external advertising service is connected.</p>');return;case'export':exportFile('panel-earnings.csv','Period,Revenue,Platform fee,Net payout,Status\nAugust 2026,2610,391.50,2218.50,Paid\nJuly 2026,2320,348,1972,Paid');return;case'exportAudit':exportFile('panel-audit.json',JSON.stringify(state.audit,null,2),'application/json');return;case'invite':modal(`<h2>Invite an author</h2><p>Give an approved creator access to their own publishing studio.</p><form id="inviteForm"><label class="field">Author email<input name="email" type="email" required placeholder="author@example.com"></label><label class="field">Role<select><option>Author — own publications only</option></select></label><button class="primary">Create demo invitation</button><p class="demo-note">Invitation is stored locally; no email is sent.</p></form>`);$('#inviteForm').onsubmit=e=>{e.preventDefault();const email=new FormData(e.target).get('email');state.invites||=[];if(state.invites.includes(email)){toast('This author already has a pending invitation');return}state.invites.push(email);log('Invited author',email);closeModal();render();toast('Demo invitation created')};return;case'suspend':modal(`<h2>${state.suspended?'Restore':'Suspend'} author access?</h2><p>${state.suspended?'Kai Nakamura will be able to submit publications again.':'Kai Nakamura will be unable to create or submit new publications. Existing published work remains available.'}</p><button class="primary" id="confirmSuspend">Confirm ${state.suspended?'restoration':'suspension'}</button>`);$('#confirmSuspend').onclick=()=>{state.suspended=!state.suspended;log(state.suspended?'Suspended author':'Restored author','Kai Nakamura');closeModal();render();toast('Author access updated')};return;}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){returnAction=null;reader=null;closeModal();$('.sidebar')?.classList.remove('open')}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search')?.focus()}if(e.key==='Tab'&&$('.modal')){const focusable=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(e=>!e.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
function syncPublications(){for(const d of state.drafts.filter(d=>d.status==='Published'&&d.kind!=='Artwork')){if(!comics.find(c=>c.id===d.id))comics.push({id:d.id,title:d.title,author:state.creatorName||'Kai Nakamura',genre:'Sci-fi',type:{'Free':'free','Membership':'membership','Individual purchase':'purchase','Membership + purchase':'both'}[d.access]||'free',rating:'New',pages:d.pages,chapters:1,art:'neon',desc:d.synopsis})}}
function continueReading(){const ids=state.history.filter(id=>!state.hidden?.includes(id)).slice(0,2);if(!ids.length)return '';return `<section class="continue-section"><div class="section-head"><h2>Back to your worlds</h2><button class="text-link" data-go="Reading history">Reading history ${icon('arrow')}</button></div><div class="continue-grid">${ids.map(id=>{const c=comics.find(c=>c.id===id);if(!c)return '';const p=state.progress?.[id]||1;return `<button class="continue-card" data-comic="${id}"><img src="assets/${c.art}.svg" alt=""><div><strong>${esc(c.title)}</strong><p>Chapter 1 · Page ${p} of ${c.pages}</p><div class="progress-track"><span style="width:${p/c.pages*100}%"></span></div></div>${icon('arrow')}</button>`}).join('')}</div></section>`}
syncPublications();
render();
